import{_ as n,a0 as d,w as o,s as p,ao as r,I as l,x as e,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Linux 系统中通过用户组来管理用户 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 系统中通过用户组来管理用户 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 系统中通过用户组来管理用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 系统中通过用户组来管理用户 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171201 How to Manage Users with Groups in Linux","title":"如何在 Linux 系统中通过用户组来管理用户","tag":"201712","desc":""},"relativePath":"201712/20171201 How to Manage Users with Groups in Linux.md","filePath":"[post].md"}'),h={name:"201712/20171201 How to Manage Users with Groups in Linux.md"};function c(u,s,g,k,b,m){const i=d("Link");return o(),p("div",null,[s[11]||(s[11]=r(`<h1 id="如何在-linux-系统中通过用户组来管理用户" tabindex="-1">如何在 Linux 系统中通过用户组来管理用户 <a class="header-anchor" href="#如何在-linux-系统中通过用户组来管理用户" aria-label="Permalink to “如何在 Linux 系统中通过用户组来管理用户”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/group-of-people-1645356_1920.jpg?itok=rJlAxBSV" alt="groups"></p><blockquote><p>本教程可以了解如何通过用户组和访问控制表（ACL）来管理用户。</p></blockquote><p>当你需要管理一台容纳多个用户的 Linux 机器时，比起一些基本的用户管理工具所提供的方法，有时候你需要对这些用户采取更多的用户权限管理方式。特别是当你要管理某些用户的权限时，这个想法尤为重要。比如说，你有一个目录，某个用户组中的用户可以通过读和写的权限访问这个目录，而其他用户组中的用户对这个目录只有读的权限。在 Linux 中，这是完全可以实现的。但前提是你必须先了解如何通过用户组和访问控制表（ACL）来管理用户。</p><p>我们将从简单的用户开始，逐渐深入到复杂的访问控制表（ACL）。你可以在你所选择的 Linux 发行版完成你所需要做的一切。本文的重点是用户组，所以不会涉及到关于用户的基础知识。</p><p>为了达到演示的目的，我将假设：</p><p>你需要用下面两个用户名新建两个用户：</p><ul><li>olivia</li><li>nathan</li></ul><p>你需要新建以下两个用户组：</p><ul><li>readers</li><li>editors</li></ul><p>olivia 属于 editors 用户组，而 nathan 属于 readers 用户组。reader 用户组对 <code>/DATA</code> 目录只有读的权限，而 editors 用户组则对 <code>/DATA</code> 目录同时有读和写的权限。当然，这是个非常小的任务，但它会给你基本的信息，你可以扩展这个任务以适应你其他更大的需求。</p><p>我将在 Ubuntu 16.04 Server 平台上进行演示。这些命令都是通用的，唯一不同的是，要是在你的发行版中不使用 <code>sudo</code> 命令，你必须切换到 root 用户来执行这些命令。</p><h3 id="创建用户" tabindex="-1">创建用户 <a class="header-anchor" href="#创建用户" aria-label="Permalink to “创建用户”">​</a></h3><p>我们需要做的第一件事是为我们的实验创建两个用户。可以用 <code>useradd</code> 命令来创建用户，我们不只是简单地创建一个用户，而需要同时创建用户和属于他们的家目录，然后给他们设置密码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo useradd -m olivia</span></span>
<span class="line"><span>sudo useradd -m nathan</span></span></code></pre></div><p>我们现在创建了两个用户，如果你看看 <code>/home</code> 目录，你可以发现他们的家目录（因为我们用了 <code>-m</code> 选项，可以在创建用户的同时创建他们的家目录。</p><p>之后，我们可以用以下命令给他们设置密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo passwd olivia</span></span>
<span class="line"><span>sudo passwd nathan</span></span></code></pre></div><p>就这样，我们创建了两个用户。</p><h3 id="创建用户组并添加用户" tabindex="-1">创建用户组并添加用户 <a class="header-anchor" href="#创建用户组并添加用户" aria-label="Permalink to “创建用户组并添加用户”">​</a></h3><p>现在我们将创建 readers 和 editors 用户组，然后给它们添加用户。创建用户组的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>addgroup readers</span></span>
<span class="line"><span>addgroup editors</span></span></code></pre></div><p>（LCTT 译注：当你使用 CentOS 等一些 Linux 发行版时，可能系统没有 <code>addgroup</code> 这个命令，推荐使用 <code>groupadd</code> 命令来替换 <code>addgroup</code> 命令以达到同样的效果）</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/groups_1.jpg?itok=BKwL89BB" alt="groups"></p><p><em>图一：我们可以使用刚创建的新用户组了。</em></p><p>创建用户组后，我们需要添加我们的用户到这两个用户组。我们用以下命令来将 nathan 用户添加到 readers 用户组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -a -G readers nathan</span></span></code></pre></div><p>用以下命令将 olivia 添加到 editors 用户组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -a -G editors olivia</span></span></code></pre></div><p>现在我们可以通过用户组来管理用户了。</p><h3 id="给用户组授予目录的权限" tabindex="-1">给用户组授予目录的权限 <a class="header-anchor" href="#给用户组授予目录的权限" aria-label="Permalink to “给用户组授予目录的权限”">​</a></h3><p>假设你有个目录 <code>/READERS</code> 且允许 readers 用户组的所有成员访问这个目录。首先，我们执行以下命令来更改目录所属用户组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chown -R :readers /READERS</span></span></code></pre></div><p>接下来，执行以下命令收回目录所属用户组的写入权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chmod -R g-w /READERS</span></span></code></pre></div><p>然后我们执行下面的命令来收回其他用户对这个目录的访问权限（以防止任何不在 readers 组中的用户访问这个目录里的文件）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chmod -R o-x /READERS</span></span></code></pre></div><p>这时候，只有目录的所有者（root）和用户组 reader 中的用户可以访问 <code>/READES</code> 中的文件。</p><p>假设你有个目录 <code>/EDITORS</code> ，你需要给用户组 editors 里的成员这个目录的读和写的权限。为了达到这个目的，执行下面的这些命令是必要的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chown -R :editors /EDITORS</span></span>
<span class="line"><span>sudo chmod -R g+w /EDITORS</span></span>
<span class="line"><span>sudo chmod -R o-x /EDITORS</span></span></code></pre></div><p>此时 editors 用户组的所有成员都可以访问和修改其中的文件。除此之外其他用户（除了 root 之外）无法访问 <code>/EDITORS</code> 中的任何文件。</p><p>使用这个方法的问题在于，你一次只能操作一个组和一个目录而已。这时候访问控制表（ACL）就可以派得上用场了。</p><h3 id="使用访问控制表-acl" tabindex="-1">使用访问控制表（ACL） <a class="header-anchor" href="#使用访问控制表-acl" aria-label="Permalink to “使用访问控制表（ACL）”">​</a></h3><p>现在，让我们把这个问题变得棘手一点。假设你有一个目录 <code>/DATA</code> 并且你想给 readers 用户组的成员读取权限，并同时给 editors 用户组的成员读和写的权限。为此，你必须要用到 <code>setfacl</code> 命令。<code>setfacl</code> 命令可以为文件或文件夹设置一个访问控制表（ACL）。</p><p>这个命令的结构如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>setfacl OPTION X:NAME:Y /DIRECTORY</span></span></code></pre></div><p>其中 OPTION 是可选选项，X 可以是 <code>u</code>（用户）或者是 <code>g</code> （用户组），NAME 是用户或者用户组的名字，/DIRECTORY 是要用到的目录。我们将使用 <code>-m</code> 选项进行修改。因此，我们给 readers 用户组添加读取权限的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo setfacl -m g:readers:rx -R /DATA</span></span></code></pre></div><p>现在 readers 用户组里面的每一个用户都可以读取 <code>/DATA</code> 目录里的文件了，但是他们不能修改里面的内容。</p><p>为了给 editors 用户组里面的用户读写权限，我们执行了以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo setfacl -m g:editors:rwx -R /DATA</span></span></code></pre></div><p>上述命令将赋予 editors 用户组中的任何成员读取权限，同时保留 readers 用户组的只读权限。</p><h3 id="更多的权限控制" tabindex="-1">更多的权限控制 <a class="header-anchor" href="#更多的权限控制" aria-label="Permalink to “更多的权限控制”">​</a></h3><p>使用访问控制表（ACL），你可以实现你所需的权限控制。你可以添加用户到用户组，并且灵活地控制这些用户组对每个目录的权限以达到你的需求。如果想了解上述工具的更多信息，可以执行下列的命令：</p><ul><li><code>man usradd</code></li><li><code>man addgroup</code></li><li><code>man usermod</code></li><li><code>man sefacl</code></li><li><code>man chown</code></li><li><code>man chmod</code></li></ul><hr>`,56)),l("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/12/how-manage-users-groups-linux"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.linux.com/learn/intro-to-linux/2017/12/how-manage-users-groups-linux",-1)])]),_:1})]),l("p",null,[s[4]||(s[4]=e("作者：[Jack Wallen] 译者：",-1)),a(i,{href:"https://github.com/imquanquan"},{default:t(()=>[...s[2]||(s[2]=[e("imquanquan",-1)])]),_:1}),s[5]||(s[5]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[3]||(s[3]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[8]||(s[8]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[6]||(s[6]=[e("LCTT",-1)])]),_:1}),s[9]||(s[9]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...s[7]||(s[7]=[e("Linux中国",-1)])]),_:1}),s[10]||(s[10]=e(" 荣誉推出",-1))])])}const y=n(h,[["render",c]]);export{C as __pageData,y as default};
